<nav class="tabs work-tabs" aria-label="<?= e(t('Project pages')) ?>"><?php foreach(['issues'=>t('Work items'),'cycles'=>t('Cycles'),'modules'=>t('Modules'),'releases'=>t('Releases'),'pages'=>t('Pages'),'views'=>t('Views'),'analytics'=>t('Analytics'),'activity'=>t('Activity'),'settings'=>t('Settings')] as $key=>$label): ?><a href="<?= $workPath ?>?tab=<?= $key ?>" <?= $tab===$key?'class="selected" aria-current="page"':'' ?>><?= $label ?></a><?php endforeach; ?></nav>
