<div class="work-issue-controls"><nav class="work-layout-switch" aria-label="<?= e(t('Work-item layout')) ?>"><?php foreach(WorkService::LAYOUTS as $value=>$label): ?><a href="<?= $workPath ?>?<?= e($workQuery(['layout'=>$value,'page'=>1])) ?>" <?= $layout===$value?'class="selected" aria-current="page"':'' ?>><?= $label ?></a><?php endforeach; ?></nav><div class="hero-actions"><a href="<?= $workPath ?>/export.csv?<?= e($workQuery()) ?>" hx-boost="false"><?= e(t('Export CSV')) ?></a><a href="<?= $workPath ?>?tab=views"><?= e(t('Save a view')) ?></a></div></div>
<section class="card work-filter-card"><form class="work-filters" method="get" action="<?= $workPath ?>"><input type="hidden" name="layout" value="<?= e($layout) ?>"><label class="work-search"><?= e(t('Search')) ?><input name="q" type="search" maxlength="200" value="<?= e($listing['filters']['q']) ?>" placeholder="Title, description or <?= e($project['identifier']) ?>-1"></label><label><?= e(t('Show')) ?><select name="scope"><?php foreach(['active'=>t('Active items'),'mine'=>t('Assigned to me'),'overdue'=>t('Overdue'),'intake'=>t('Intake'),'rejected'=>t('Rejected requests'),'archived'=>t('Archived'),'trash'=>t('Trash')] as $value=>$label): ?><option value="<?= $value ?>" <?= $listing['filters']['scope']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label><?= e(t('State')) ?><select name="state"><option value=""><?= e(t('All states')) ?></option><?php foreach($states as $state): ?><option value="<?= e($state['id']) ?>" <?= $listing['filters']['state']===$state['id']?'selected':'' ?>><?= e($state['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Priority')) ?><select name="priority"><option value=""><?= e(t('All priorities')) ?></option><?php foreach(WorkService::PRIORITIES as $key=>$label): ?><option value="<?= $key ?>" <?= $listing['filters']['priority']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><details class="work-more-filters"><summary><?= e(t('More filters')) ?></summary><div class="form-grid"><label><?= e(t('Type')) ?><select name="issue_type"><option value=""><?= e(t('All types')) ?></option><?php foreach(WorkService::TYPES as $value=>$label): ?><option value="<?= $value ?>" <?= $listing['filters']['issue_type']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label><?= e(t('Release')) ?><select name="release"><option value=""><?= e(t('All releases')) ?></option><?php foreach($releases as $release): ?><option value="<?